/** Resolves only a server-persisted, body-free occurrence scope.  Fixture
 * references remain compatible through the legacy map above. */
export function resolveRegisteredPreparationScopeForOccurrence(input:{store:{organizationId:string;registeredMeetingPreparationScopes?:readonly {contractVersion?:string;scopeId:string;organizationId:string;questionId:string;conversationId:string;seriesId:string;scopeDigest:string;sourceVersions:readonly {sourceBindingId:string;sourceContentVersionId:string;normalizedContentDigest:string}[]}[]};organizationId:string;questionId:string;conversationId:string;seriesId:string;scopeId?:string}){
  const matches=(input.store.registeredMeetingPreparationScopes??[]).filter(value=>value.organizationId===input.organizationId&&value.questionId===input.questionId&&value.conversationId===input.conversationId&&value.seriesId===input.seriesId&&(!input.scopeId||value.scopeId===input.scopeId));
  if(matches.length!==1||!matches[0]!.sourceVersions.length||matches[0]!.contractVersion!=="1")throw new Error("Registered meeting preparation scope is unavailable.");
  const scope=matches[0]!,{scopeDigest,...unsigned}=scope;
  if(scopeDigest!==productArtifactBodyDigest(unsigned))throw new Error("Registered meeting preparation scope is unavailable.");
  return scope;
}
export function registeredPreparationSourceRefs(input:Parameters<typeof resolveRegisteredPreparationScopeForOccurrence>[0]):string[]{
  return resolveRegisteredPreparationScopeForOccurrence(input).sourceVersions.map(value=>value.sourceContentVersionId).sort();
}
const canonicalPreparationSourceRefs=(refs:readonly string[]):string[]=>{const canonical=[...refs].sort();if(!canonical.length||new Set(canonical).size!==canonical.length)throw new Error("Chief first Prepare source basis is unavailable.");return canonical};

export async function executeCloseAndContinueOccurrence1Boundary(input: {
  argumentsList: readonly unknown[];
  server: Pick<LeadershipConversationServerComposition, "workspace" | "publishClosureWhatChanged" | "prepareNextOccurrence">;
  identity: { userId: string; organizationId: string; questionId: string; conversationId: string };
  initialWorkspace: LeadershipConversationWorkspaceV1;
  completeOccurrence(): Promise<LeadershipConversationWorkspaceV1>;
}) {
  assertCloseAndContinueOccurrence1Arguments(input.argumentsList);
  let current = input.initialWorkspace;
  if (!current.closureCompletion) current = await input.completeOccurrence();
  if (current.currentStep === "what-changed") current = await input.server.publishClosureWhatChanged(input.identity);
  return input.server.prepareNextOccurrence(input.identity);
}

const PURPOSE = "leadership-conversation-capture" as const;
