const clock = { now: () => resolveLeadershipConversationEvaluationTime() };
function personaKeyFromActorRef(actorRef:string):SandboxPersonaKey{const prefix="sandbox-persona:",value=actorRef.startsWith(prefix)?actorRef.slice(prefix.length):"";if(!SANDBOX_PERSONAS.some(item=>item.key===value))throw new Error("Canonical Product materialization actor reference is invalid.");return value as SandboxPersonaKey;}

function exactDevelopmentIdentity(userId:string, organizationId:string): boolean {
  if (process.env.NODE_ENV === "production" || organizationId !== SANDBOX_ORGANIZATION_ID) return false;
  try { return resolvePersonaForSignedInUser(userId)?.userId === userId; } catch { return false; }
}

function resolveSourceScopedAnalysisTimeout(value:string|undefined):number|null{if(value===undefined)return DEFAULT_SOURCE_SCOPED_ANALYSIS_TIMEOUT_MS;if(!/^(0|[1-9][0-9]*)$/.test(value))return null;const timeoutMs=Number(value);return Number.isSafeInteger(timeoutMs)&&timeoutMs>=MIN_SOURCE_SCOPED_ANALYSIS_TIMEOUT_MS&&timeoutMs<=MAX_SOURCE_SCOPED_ANALYSIS_TIMEOUT_MS?timeoutMs:null;}
async function lifecycleRootReady(root:string){try{if(!path.isAbsolute(root))return false;for(const directory of [root,path.join(root,"attempts"),path.join(root,"active")]){const state=await lstat(directory);if(!state.isDirectory()||state.isSymbolicLink()||(state.mode&0o777)!==0o700||state.uid!==process.getuid?.())return false;}return true;}catch{return false;}}

function scoped(userId:string, organizationId:string, operation:ScopedGovernanceOperation, authorized:(userId:string,organizationId:string)=>boolean, at=FIXED_TIME, purpose:string=PURPOSE, authorityGrants?:readonly ScopedAuthorityGrant[]) {
  const requestedScope={organizationId,type:"organization" as const,id:organizationId};
  const defaults:ScopedAuthorityGrant[]=authorized(userId,organizationId)?[{authorityRef:`leadership-conversation:${userId}`,policyRef:"leadership-conversation-development:v1",organizationId,subjectId:userId,scope:requestedScope,operations:["source-binding:register-local","source-binding:resolve-current","source-binding:revise-availability","source-content:write","source-content:read-for-proposal","source-content:read-for-evidence-admission","source-content:read-for-claim-support","source-content:reset-development","product-artifact:read","product-artifact:reuse","product-artifact:compare","product-artifact:prepare-again","product-artifact:create-successor","historical-checkpoint-lifecycle-link:publish","historical-checkpoint-lifecycle-link:list","historical-checkpoint-lifecycle-link:read","leadership-history:read","leadership-history:list",CANONICAL_UNDERSTANDING_REVISION_OPERATION,CANONICAL_UNDERSTANDING_COMPOSITION_EVALUATION_OPERATION],sensitivity:["standard"],relationship:"direct",status:"active",validFrom:"2026-01-01T00:00:00.000Z"}]:[];
  return resolveScopedGovernanceContext({organizationId,subjectId:userId,requestedScope,operation,purpose,sensitivity:"standard",evaluatedAt:at,temporal:{mode:"current"},serverResolvedAuthority:authorityGrants??defaults});
}

function investigation(runtime:Parameters<typeof evolveOrganizationRuntime>[0]["runtime"], question:string, contribution:CanonicalEvidenceContribution) {
  const index=runtime.memory.canonicalScopeLineageIndex,topology=index?readCanonicalScopeLineageTopology(index):undefined;
  if(!index||!topology)throw new Error("Leadership Conversation canonical lineage is unavailable.");
  const normalizedContent=decodeAndNormalizeSourceContent(new TextEncoder().encode(contribution.content)).normalizedText;
  const input={company:runtime.metadata.name||runtime.metadata.organizationId,website:runtime.metadata.website??"",industry:runtime.metadata.industry??"",question,context:"",evidenceSources:[{sourceId:contribution.sourceId,sourceType:contribution.sourceType,observedAt:contribution.contributedAt,contentDigest:sourceContentDigest(new TextEncoder().encode(normalizedContent)),content:contribution.content}]};
  const lineage={organizationId:runtime.metadata.organizationId,effectiveAt:contribution.contributedAt,topologyRevisions:[topology],sourceBindingRevisions:index.sourceBindings,existingEvidenceAttributions:index.evidenceAttributions};
  return {input,lineage};
}

